-- Coaching tools: Body Weight Development 1, 2 and 5 (from the Word files). Skips any already added.
insert into coaching_tools (title, description, category, kind, body)
select 'Body Weight Development 1', 'Body weight circuit — reps / times with columns to fill in', 'Body weight development', 'page', '<p>Write the reps done (or tick when complete) in each column — one column per round or session.</p><table><thead><tr><th>Exercise</th><th>Reps / time</th><th>Reps / ✓</th><th>Reps / ✓</th><th>Reps / ✓</th><th>Reps / ✓</th></tr></thead><tbody><tr><td>Stretch Flow</td><td>2 Min</td><td></td><td></td><td></td><td></td></tr><tr><td>High Plank</td><td>30 secs</td><td></td><td></td><td></td><td></td></tr><tr><td>Side plank</td><td>30 secs</td><td></td><td></td><td></td><td></td></tr><tr><td>Bridge Hold</td><td>30 secs each leg</td><td></td><td></td><td></td><td></td></tr><tr><td>Push Ups - incline</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Shoulder Push Hold</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Palm Squeeze</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Grip and pull</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Squats</td><td>10</td><td></td><td></td><td></td><td></td></tr><tr><td>High Knee hold</td><td>30 secs</td><td></td><td></td><td></td><td></td></tr><tr><td>Standing Side leg raises</td><td>10</td><td></td><td></td><td></td><td></td></tr><tr><td>Single Leg RDL hold</td><td>30 secs</td><td></td><td></td><td></td><td></td></tr><tr><td>Lunge Hold</td><td>30 secs</td><td></td><td></td><td></td><td></td></tr><tr><td>Squat jumps (Ninja feet)</td><td>10</td><td></td><td></td><td></td><td></td></tr></tbody></table>'
where not exists (select 1 from coaching_tools where title = 'Body Weight Development 1');

insert into coaching_tools (title, description, category, kind, body)
select 'Body Weight Development 2', 'Body weight circuit — reps / times with columns to fill in', 'Body weight development', 'page', '<p>Write the reps done (or tick when complete) in each column — one column per round or session.</p><table><thead><tr><th>Exercise</th><th>Reps / time</th><th>Reps / ✓</th><th>Reps / ✓</th><th>Reps / ✓</th><th>Reps / ✓</th></tr></thead><tbody><tr><td>Stretch Flow</td><td>2 Min x 1</td><td></td><td></td><td></td><td></td></tr><tr><td>High Plank</td><td>1 min</td><td></td><td></td><td></td><td></td></tr><tr><td>Side plank Pick ups</td><td>25</td><td></td><td></td><td></td><td></td></tr><tr><td>Bridge Hold</td><td>1 min each leg</td><td></td><td></td><td></td><td></td></tr><tr><td>Push Ups</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Shoulder Push Ups</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Quarter Push Ups</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Snake Push Ups</td><td>12-15</td><td></td><td></td><td></td><td></td></tr><tr><td>Plyo Push Ups</td><td><p>4 x 2 </p><p>30 sec rest</p></td><td></td><td></td><td></td><td></td></tr><tr><td>Squats</td><td>25 each leg</td><td></td><td></td><td></td><td></td></tr><tr><td>Standing Side leg raises</td><td>15 - 25</td><td></td><td></td><td></td><td></td></tr><tr><td>Sumo Squats</td><td>25</td><td></td><td></td><td></td><td></td></tr><tr><td>Standing Side leg raises off the floor</td><td>10 – 15 each leg</td><td></td><td></td><td></td><td></td></tr><tr><td>Lunge Pulse</td><td>25 each leg</td><td></td><td></td><td></td><td></td></tr><tr><td>Wall Sits</td><td><p>1 min </p><p>30 sec rest x 2</p></td><td></td><td></td><td></td><td></td></tr><tr><td>Squat jumps</td><td>25</td><td></td><td></td><td></td><td></td></tr><tr><td>Crunches</td><td>2 mins</td><td></td><td></td><td></td><td></td></tr></tbody></table>'
where not exists (select 1 from coaching_tools where title = 'Body Weight Development 2');

insert into coaching_tools (title, description, category, kind, body)
select 'Body Weight Development 5', 'Partner / ball circuit', 'Body weight development', 'page', '<ol><li>Wall sits + Juggle/Throw and pass</li><li>TRX Hang + catch</li><li>Tricep Hold</li><li>Jumps</li><li>Spider throw and catch</li><li>Plank throw and catch</li><li>Skiers + Balance</li></ol>'
where not exists (select 1 from coaching_tools where title = 'Body Weight Development 5');

select title, category, kind, length(body) as size from coaching_tools where category = 'Body weight development' order by title;
